    "schema_json": "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://opentakeoff.kentucky-ai.com/protocol/v1/measurement.schema.json\",\n  \"title\": \"Measurement (draft)\",\n  \"type\": \"object\",\n  \"properties\": {\n    \"id\": {\n      \"type\": \"string\",\n      \"minLength\": 1\n    },\n    \"sheet_id\": {\n      \"type\": \"string\",\n      \"minLength\": 1\n    },\n    \"condition_id\": {\n      \"type\": \"string\",\n      \"minLength\": 1\n    },\n    \"measure_role\": {\n      \"enum\": [\n        \"floor_area\",\n        \"deduct\",\n        \"linear\",\n        \"surface_area\",\n        \"count\"\n      ]\n    },\n    \"verts_norm\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"$ref\": \"common.schema.json#/$defs/point\"\n      },\n      \"minItems\": 1\n    },\n    \"verts_norm_holes\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"array\",\n        \"items\": {\n          \"$ref\": \"common.schema.json#/$defs/point\"\n        }\n      }\n    },\n    \"computed\": {\n      \"$ref\": \"common.schema.json#/$defs/computed\"\n    },\n    \"height_ft\": {\n      \"type\": \"number\"\n    },\n    \"rise_ft\": {\n      \"type\": \"number\",\n      \"minimum\": 0,\n      \"description\": \"Linear runs only: this run's own vertical leg UP in feet, overriding the condition's rise_ft (0 included). Absent means the condition default applies.\"\n    },\n    \"drop_ft\": {\n      \"type\": \"number\",\n      \"minimum\": 0,\n      \"description\": \"Linear runs only: this run's own vertical leg DOWN in feet, overriding the condition's drop_ft (0 included). Absent means the condition default applies.\"\n    },\n    \"label\": {\n      \"type\": \"string\"\n    },\n    \"curved\": {\n      \"type\": \"boolean\"\n    },\n    \"cuts_shape_id\": {\n      \"type\": \"string\",\n      \"minLength\": 1\n    },\n    \"origin\": {\n      \"$ref\": \"provenance.schema.json\"\n    },\n    \"created_at\": {\n      \"$ref\": \"common.schema.json#/$defs/timestamp\"\n    },\n    \"updated_at\": {\n      \"$ref\": \"common.schema.json#/$defs/timestamp\"\n    },\n    \"author\": {\n      \"type\": \"string\"\n    },\n    \"updated_by\": {\n      \"type\": \"string\"\n    }\n  },\n  \"required\": [\n    \"id\",\n    \"sheet_id\",\n    \"condition_id\",\n    \"measure_role\",\n    \"verts_norm\",\n    \"computed\"\n  ],\n  \"additionalProperties\": true,\n  \"description\": \"One existing shape record. Legacy curved=true means spline control points; new baked arcs use ordinary vertices and origin.curved. Do not conflate or regenerate them.\"\n}\n"
